data.CSS:
@font-face { font-family:"Fraunces"; font-weight:600; font-display:swap; src:url("/fonts/fraunces-600.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:400; font-display:swap; src:url("/fonts/inter-400.woff2") format("woff2"); }
@font-face { font-family:"Inter"; font-weight:600; font-display:swap; src:url("/fonts/inter-600.woff2") format("woff2"); }
:root { --sea:#0E3B4F; --sand:#F2E6D0; --coral:#E4572E; --foam:#F7FAFA; --ink:#14232b; --muted:#40535c; --rule:#d8e0e2;
  --display:"Fraunces", Georgia, serif; --body:"Inter", system-ui, sans-serif; }
* { box-sizing:border-box; }
body { margin:0; background:var(--foam); color:var(--ink); font:17px/1.65 var(--body); }
img { display:block; max-width:100%; height:auto; }
a { color:var(--sea); text-decoration-color:var(--coral); text-underline-offset:.2em; }
a:hover { text-decoration-thickness:2px; }
h1, h2, h3 { font-family:var(--display); font-weight:600; color:var(--sea); line-height:1.15; margin:0 0 .5em; }
h1 { font-size:clamp(2.1rem, 4vw, 3.2rem); }
h2 { font-size:clamp(1.5rem, 2.6vw, 2rem); }
h3 { font-size:1.25rem; }
.q-wrap { max-width:72rem; margin:0 auto; padding:0 1.25rem; }
.q-narrow { max-width:44rem; }
.q-header { background:var(--sea); color:#fff; }
.q-header .q-wrap { display:flex; flex-wrap:wrap; align-items:center; gap:1rem 2rem; padding-top:1rem; padding-bottom:1rem; }
.q-brand { font-family:var(--display); font-size:1.5rem; color:#fff; text-decoration:none; letter-spacing:.02em; }
.q-brand span { color:var(--sand); }
.q-nav ul, .q-langs { display:flex; flex-wrap:wrap; gap:.25rem 1.25rem; list-style:none; margin:0; padding:0; }
.q-nav a, .q-langs a { color:#fff; text-decoration:none; font-weight:600; }
.q-nav a:hover, .q-langs a:hover { text-decoration:underline; text-decoration-color:var(--coral); }
.q-langs { margin-left:auto; font-size:.9rem; }
.q-langs a { text-transform:uppercase; letter-spacing:.06em; border:1px solid rgba(255,255,255,.45); border-radius:.25rem; padding:.15rem .5rem; }
.q-hero { position:relative; background:var(--sea); color:#fff; }
.q-hero img { width:100%; aspect-ratio:16/7; object-fit:cover; opacity:.82; }
.q-hero .q-hero-text { position:absolute; inset:auto 0 0 0; padding:2.5rem 0; background:linear-gradient(transparent, rgba(8,32,43,.88)); }
.q-hero h1 { color:#fff; max-width:40rem; }
.q-hero p { max-width:36rem; font-size:1.15rem; margin:0 0 1.25rem; }
.q-button { display:inline-block; background:var(--coral); color:#14232b; font-weight:600; text-decoration:none; padding:.75rem 1.4rem; border-radius:.3rem; }
.q-button:hover { background:#f07a55; }
.q-section { padding:3.5rem 0; }
.q-section + .q-section { border-top:1px solid var(--rule); }
.q-band { background:var(--sand); }
.q-lead { font-size:1.2rem; color:var(--muted); max-width:44rem; }
.q-cards { display:grid; gap:1.75rem; grid-template-columns:repeat(auto-fill, minmax(16rem, 1fr)); list-style:none; margin:2rem 0 0; padding:0; } .q-cards-row { grid-template-columns:repeat(auto-fit, minmax(16rem, 1fr)); }
.q-card { background:#fff; border:1px solid var(--rule); border-radius:.4rem; overflow:hidden; display:flex; flex-direction:column; }
.q-card img { aspect-ratio:3/2; object-fit:cover; width:100%; }
.q-card-body { padding:1.1rem 1.25rem 1.4rem; }
.q-card h2, .q-card h3 { font-size:1.3rem; margin-bottom:.35rem; }
.q-card a { text-decoration:none; }
.q-card a:hover { text-decoration:underline; text-decoration-color:var(--coral); }
.q-card p { margin:0; color:var(--muted); }
.q-split { display:grid; gap:2.5rem; grid-template-columns:minmax(0, 3fr) minmax(0, 2fr); align-items:start; }
.q-facts { display:grid; grid-template-columns:auto 1fr; gap:.5rem 1.25rem; margin:0; padding:1.25rem 1.5rem; background:var(--sand); border-left:4px solid var(--coral); border-radius:.25rem; }
.q-facts dt { font-weight:600; color:var(--sea); }
.q-facts dd { margin:0; }
.q-figure { margin:0 0 2rem; }
.q-figure figcaption { font-size:.9rem; color:var(--muted); margin-top:.5rem; }
.q-byline { color:var(--muted); font-size:.95rem; }
.q-prose p, .q-prose ul { margin:0 0 1.1rem; }
.q-person { display:flex; gap:1rem; align-items:center; }
.q-person img { width:5rem; height:5rem; border-radius:50%; object-fit:cover; }
.q-footer { background:var(--sea); color:var(--sand); padding:2.5rem 0; margin-top:3rem; font-size:.95rem; }
.q-footer a { color:#fff; }
.q-footer .q-wrap { display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; }
@media (max-width: 48rem) { .q-split { grid-template-columns:1fr; } .q-hero img { aspect-ratio:4/3; opacity:1; } .q-hero .q-hero-text { position:static; background:var(--sea); padding:1.75rem 0 2rem; } .q-langs { margin-left:0; } }

.q-built { display:grid; grid-template-columns:max-content 1fr; gap:.5rem 1rem; margin:0 0 2rem; padding:1.1rem 1.25rem; background:var(--sand); border-radius:.4rem;}
.q-built dt { font-weight:600;}
.q-built dd { margin:0; overflow-wrap:anywhere;}
.q-built code, .q-prose code { font-family:ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size:.9em;}
.q-search { display:flex; flex-wrap:wrap; gap:.75rem; align-items:end; margin:0 0 2rem;}
.q-search label { display:block; font-weight:600; margin-bottom:.35rem;}
.q-search input { font:inherit; padding:.7rem .8rem; border:1px solid var(--rule); border-radius:.3rem; min-width:16rem;}
.q-search button { font:inherit; border:0; cursor:pointer;}
.q-results { list-style:none; padding:0; margin:0 0 2rem;}
.q-results li { padding:.75rem 0; border-bottom:1px solid var(--rule);}
.q-results p { margin:.25rem 0 0; color:var(--muted);}

.q-nav a[aria-current=page] { text-decoration:underline; text-decoration-color:var(--coral); text-decoration-thickness:2px; text-underline-offset:.4em;}
.q-nav a.is-ancestor { text-decoration:underline; text-decoration-color:rgba(255,255,255,.45); text-underline-offset:.4em;}

.q-skip { position:absolute; left:1rem; top:-3rem; z-index:10; background:var(--sand); color:var(--ink); padding:.5rem 1rem; border-radius:.3rem; font-weight:600;}
.q-skip:focus { top:1rem;}
